(()=>{'use strict';const params=new URLSearchParams(location.search);if(!params.size)return;let changed=false;for(const id of ['place','type','deal','price','area','rooms','sqm']){const value=params.get(id),field=document.getElementById(id);if(value===null||!field)continue;if(id==='place'){field.value=value.slice(0,100);changed=true}else if(['type','deal'].includes(id)){if([...field.options].some(o=>o.value===value)){field.value=value;changed=true}}else if(value!==''&&Number.isFinite(Number(value))&&Number(value)>=0&&Number(value)<=1e8){field.value=value;changed=true}}if(changed){const note=document.createElement('p');note.className='notice';note.textContent='Suchfilter aus deinem Startseiten-Assistenten übernommen. Bitte prüfen und die Suche starten.';document.getElementById('form').prepend(note)}})();
